Your expense tracker is below. Add an item, pick a category and amount, and the total and category bars update as you go. Set a monthly budget to see what's left. Entries stay only while this page is open.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body{font-family:Segoe UI,Arial,sans-serif;margin:0;padding:16px;background:#f6f6f8;color:#222}
  h1{font-size:18px;margin:0 0 12px}
  .card{background:#fff;border-radius:10px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px rgba(0,0,0,.1)}
  .row{display:flex;gap:8px;flex-wrap:wrap}
  input,select,button{font:inherit;padding:8px;border:1px solid #ccc;border-radius:6px}
  input{flex:1;min-width:90px}
  button{background:#2b6cb0;color:#fff;border:none;cursor:pointer}
  button.x{background:none;color:#c53030;padding:2px 8px}
  .big{font-size:24px;font-weight:600}
  .muted{color:#666;font-size:13px}
  .bar{height:10px;background:#2b6cb0;border-radius:5px}
  .track{background:#e2e8f0;border-radius:5px;margin:2px 0 8px}
  .item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee}
  .over{color:#c53030}
</style>
</head>
<body>
<h1>Monthly expenses</h1>

<div class="card">
  <div class="row">
    <input id="name" placeholder="What for? (e.g. Groceries)">
    <select id="cat">
      <option>Food</option><option>Rent</option><option>Travel</option>
      <option>Bills</option><option>Shopping</option><option>Other</option>
    </select>
    <input id="amt" type="number" min="0" placeholder="Amount (₹)">
    <button id="add">Add</button>
  </div>
</div>

<div class="card">
  <div class="muted">Spent this month</div>
  <div class="big" id="total">₹0</div>
  <div class="row" style="margin-top:8px;align-items:center">
    <span class="muted">Budget (₹)</span>
    <input id="budget" type="number" min="0" placeholder="e.g. 40000">
  </div>
  <div id="left" class="muted" style="margin-top:6px"></div>
</div>

<div class="card">
  <div class="muted" style="margin-bottom:6px">By category</div>
  <div id="cats"></div>
</div>

<div class="card">
  <div class="muted">Entries</div>
  <div id="list"></div>
</div>

<script>
  var items = [];
  var $ = function(id){return document.getElementById(id)};
  function inr(n){return '₹' + Number(n).toLocaleString('en-IN')}
  function render(){
    var total = items.reduce(function(s,i){return s+i.amt},0);
    $('total').textContent = inr(total);
    var b = Number($('budget').value);
    if(b > 0){
      var d = b - total;
      $('left').textContent = d >= 0 ? inr(d) + ' left of ' + inr(b) : inr(-d) + ' over budget';
      $('left').className = d >= 0 ? 'muted' : 'muted over';
    } else { $('left').textContent = '' }
    var by = {};
    items.forEach(function(i){by[i.cat] = (by[i.cat]||0) + i.amt});
    var html = '';
    Object.keys(by).forEach(function(c){
      var pct = total ? Math.round(by[c]/total*100) : 0;
      html += '<div class="item" style="border:0;padding:0"><span>' + c + '</span><span>' + inr(by[c]) + ' (' + pct + '%)</span></div>' +
              '<div class="track"><div class="bar" style="width:' + pct + '%"></div></div>';
    });
    $('cats').innerHTML = html || '<span class="muted">Nothing yet</span>';
    $('list').innerHTML = items.map(function(i,k){
      return '<div class="item"><span>' + i.name.replace(/</g,'&lt;') + ' <span class="muted">· ' + i.cat + '</span></span>' +
             '<span>' + inr(i.amt) + ' <button class="x" data-k="' + k + '">✕</button></span></div>';
    }).join('') || '<span class="muted">No entries yet</span>';
  }
  $('add').onclick = function(){
    var amt = Number($('amt').value);
    if(!(amt > 0)) return;
    items.push({name: $('name').value.trim() || 'Expense', cat: $('cat').value, amt: amt});
    $('name').value = ''; $('amt').value = '';
    render();
  };
  $('list').onclick = function(e){
    var k = e.target.getAttribute('data-k');
    if(k !== null){ items.splice(Number(k),1); render(); }
  };
  $('budget').oninput = render;
  render();
</script>
</body>
</html>
```

Here is a water tracker with a goal of 8 glasses. Tap + after each glass and − to undo. It starts fresh each day if your device lets the page remember.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: sans-serif; text-align: center; padding: 24px; background: #eef7fc; color: #123; }
  h2 { margin: 0 0 4px; }
  .count { font-size: 56px; margin: 12px 0; }
  .glasses { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin: 16px auto; max-width: 320px; }
  .g { width: 56px; height: 72px; border: 3px solid #3b9ad9; border-radius: 4px 4px 14px 14px; background: #fff; }
  .g.full { background: #6ec1f2; }
  button { font-size: 22px; padding: 10px 22px; margin: 4px; border: 0; border-radius: 8px; background: #3b9ad9; color: #fff; cursor: pointer; }
  button.alt { background: #9bb; }
  #msg { min-height: 24px; margin-top: 12px; font-weight: bold; }
</style>
</head>
<body>
  <h2>Water today</h2>
  <div id="date"></div>
  <div class="count"><span id="n">0</span> / 8</div>
  <div class="glasses" id="glasses"></div>
  <button onclick="change(1)">+ Glass</button>
  <button class="alt" onclick="change(-1)">− Undo</button>
  <button class="alt" onclick="reset()">Reset</button>
  <div id="msg"></div>
<script>
  var GOAL = 8;
  var key = "water-" + new Date().toISOString().slice(0, 10);
  var n = 0;
  try { n = parseInt(localStorage.getItem(key)) || 0; } catch (e) {}
  document.getElementById("date").textContent = new Date().toDateString();

  function save() { try { localStorage.setItem(key, n); } catch (e) {} }
  function change(d) { n = Math.max(0, n + d); save(); draw(); }
  function reset() { n = 0; save(); draw(); }

  function draw() {
    document.getElementById("n").textContent = n;
    var html = "";
    for (var i = 0; i < GOAL; i++) {
      html += '<div class="g' + (i < n ? ' full' : '') + '"></div>';
    }
    document.getElementById("glasses").innerHTML = html;
    document.getElementById("msg").textContent =
      n >= GOAL ? "Goal reached. Well done!" : (GOAL - n) + " more to go";
  }
  draw();
</script>
</body>
</html>
```
